INSERT INTO public.words (id, word, meaning, detailed_meaning, news_example, hint, related_words, visuals, sources) VALUES
(1061,'소비자 균형 조건','한계대체율과 상대가격이 같아져야 효용이 가장 커진다는 조건','소비자 균형 조건은 무차별곡선과 예산선이 접하는 점에서 MRS = Px ÷ Py가 성립한다는 것이다. MRS가 상대가격보다 크면 X를 늘리고, 작으면 Y를 늘리는 쪽이 이득이다. MRS = MUx ÷ MUy이므로 이 조건은 한계효용 균등의 법칙과 같은 말이다.','','ㅅㅂㅈㄱㅎㅈㄱ',ARRAY['한계효용 균등의 법칙','한계대체율','상대가격','소비자 균형']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "내 마음속 교환 비율과 시장의 교환 비율이 같아지는 곳에서\n더 바꿀 이유가 없어져요. 그게 균형이에요."}, {"type": "table", "title": "X재 200원, Y재 100원(상대가격 2)", "columns": ["점", "비교", "움직일 방향"], "rows": [["B(Y가 많음)", "MRS > Px ÷ Py", "X 늘리고 Y 줄임"], ["C(X가 많음)", "MRS < Px ÷ Py", "Y 늘리고 X 줄임"], ["A(접점)", "MRS = Px ÷ Py", "그대로"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1062,'한계효용 균등의 법칙','각 재화에 마지막으로 쓴 1원의 만족이 같아질 때 효용이 최대라는 원리','한계효용 균등의 법칙은 MUx ÷ Px = MUy ÷ Py가 성립하도록 돈을 나눠 쓸 때 효용이 가장 커진다는 원리다. 1원당 효용이 큰 재화를 늘리면 한계효용 체감으로 그 값이 줄어들어 결국 두 값이 같아진다. 한계효용 자체가 아니라 가격으로 나눈 1원당 효용을 비교해야 한다.','','ㅎㄱㅎㅇㄱㄷㅇㅂㅊ',ARRAY['소비자 균형 조건','한계효용','소비자 균형']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "같은 돈이면 더 뿌듯한 쪽에 먼저 써요.\n마지막 1원이 어디에 쓰이든 똑같이 뿌듯해지면 멈춰요."}, {"type": "table", "title": "1원당 효용 비교", "columns": ["재화", "한계효용", "가격", "1원당 효용"], "rows": [["X재", "2", "3원", "약 0.67"], ["Y재", "0.5", "1원", "0.5"]], "caption": "X재의 1원당 효용이 더 크니 X재를 늘리고 Y재를 줄여요."}, {"type": "text", "title": "헷갈리기 쉬운 점", "body": "한계효용이 큰 재화를 늘리는 게 아니에요.\n가격으로 나눈 1원당 효용을 비교해야 해요."}]'::jsonb,ARRAY['tesat']::text[]),
(1063,'수요곡선 도출','가격별로 소비자 균형점을 구해 가격과 수요량을 이어 수요곡선을 그리는 과정','수요곡선 도출은 한 재화 가격만 바꿔 가며 MRS = Px ÷ Py와 예산식을 연립해 균형 수요량을 구하는 과정이다. 가격이 오르면 균형 수요량이 줄어드는 점들을 이으면 우하향하는 수요곡선이 된다. 관찰에서 나온 수요의 법칙에 효용 극대화라는 근거를 붙여준다.','','ㅅㅇㄱㅅㄷㅊ',ARRAY['수요함수','소비자 균형','수요의 법칙','가격효과']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "값이 바뀔 때마다 장바구니를 다시 짜서\n그때 산 개수를 점으로 찍어 이으면 수요곡선이 돼요."}, {"type": "flow", "title": "소득 100, U = x^0.5 × y^0.5의 균형", "steps": ["MRS = y ÷ x", "Px 2, Py 4라 y ÷ x = 0.5", "예산식 2x + 4y = 100에 대입", "x = 25, y = 12.5"]}, {"type": "table", "title": "x재 가격별 균형 수요량(x = 50 ÷ Px)", "columns": ["x재 가격", "균형 수요량"], "rows": [["4원", "12.5개"], ["2원", "25개"], ["1원", "50개"]], "caption": "점들을 이으면 우하향하는 수요곡선이에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1064,'가격효과','한 재화 가격이 바뀔 때 그 재화의 수요량이 바뀌는 전체 효과','가격효과는 대체효과와 소득효과를 더한 것이다. 정상재는 두 효과가 같은 방향이라 가격이 내리면 수요량이 확실히 늘고, 열등재는 두 효과가 반대 방향이다. 기펜재는 소득효과가 대체효과보다 커서 가격이 내려도 수요량이 줄어든다.','','ㄱㄱㅎㄱ',ARRAY['대체효과','소득효과','기펜재','열등재']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "라면이 싸지면 \"다른 것 대신 라면을 살까\"와\n\"돈이 남네\"가 동시에 일어나요.\n이 둘을 합친 게 가격효과예요."}, {"type": "table", "title": "가격이 내릴 때", "columns": ["재화", "대체효과", "소득효과", "결론"], "rows": [["정상재", "증가", "증가", "확실히 증가"], ["열등재", "증가", "감소(더 작음)", "조금 증가"], ["기펜재", "증가", "감소(더 큼)", "오히려 감소"]]}, {"type": "text", "title": "왜 중요할까?", "body": "모든 기펜재는 열등재지만 모든 열등재가 기펜재는 아니에요.\n결론은 소득효과의 방향과 크기가 정해요."}]'::jsonb,ARRAY['tesat']::text[]),
(1065,'대체효과','상대가격이 바뀌어 상대적으로 싸진 재화로 바꿔 사는 효과','대체효과는 효용을 처음과 같게 둔 채 상대가격 변화만으로 수요량이 바뀌는 효과다. 재화 종류와 상관없이 늘 가격과 반대 방향으로, 값이 내리면 수요량이 늘고 오르면 준다. 그래프에서는 같은 무차별곡선 위의 이동으로 나타난다.','','ㄷㅊㅎㄱ',ARRAY['소득효과','가격효과','상대가격','대체재']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "콜라 값이 오르면 사이다가 상대적으로 싸 보여요.\n그래서 콜라를 줄이고 사이다를 늘려요."}, {"type": "table", "title": "대체효과 vs 소득효과", "columns": ["구분", "대체효과", "소득효과"], "rows": [["원인", "상대가격 변화", "실질소득 변화"], ["방향", "늘 가격과 반대", "정상재 +, 열등재 -"], ["그래프", "같은 무차별곡선 위 이동", "다른 무차별곡선으로 이동"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1066,'소득효과','가격 변화로 실질소득이 바뀌어 수요량이 달라지는 효과','소득효과는 가격이 내려 같은 돈으로 더 많이 살 수 있게 되면서, 곧 실질소득이 늘면서 수요량이 바뀌는 효과다. 정상재는 실질소득이 늘면 더 사고, 열등재는 덜 산다. 열등재 가운데 소득효과가 대체효과보다 큰 재화가 기펜재다.','','ㅅㄷㅎㄱ',ARRAY['대체효과','가격효과','실질소득','기펜재']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "월급은 그대로인데 콜라가 100원에서 50원이 되면\n같은 돈으로 콜라를 2배 살 수 있어요.\n이렇게 넉넉해진 만큼 소비가 바뀌는 게 소득효과예요."}, {"type": "table", "title": "명목소득 vs 실질소득", "columns": ["구분", "뜻"], "rows": [["명목소득", "지갑에 든 돈의 금액"], ["실질소득", "그 돈으로 살 수 있는 물건의 양"]]}, {"type": "table", "title": "값이 내릴 때 소득효과", "columns": ["재화", "소득이 늘면", "소득효과"], "rows": [["정상재", "더 삼", "수요량 증가"], ["열등재", "덜 삼", "수요량 감소"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1067,'생산의 단기와 장기','바꿀 수 없는 생산요소가 있는지로 나누는 생산 기간 구분','생산에서 단기는 공장·기계처럼 당장 바꿀 수 없는 생산요소가 하나라도 있는 기간이다. 장기는 노동과 자본을 포함한 모든 생산요소를 바꿀 수 있는 기간이다. 기준은 달력 시간이 아니라 생산요소를 바꿀 수 있느냐여서 업종마다 장기의 길이가 다르다.','','ㅅㅅㅇㄷㄱㅇㅈㄱ',ARRAY['고정 생산요소','가변 생산요소','생산함수','수확체감의 법칙']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "손님이 몰릴 때 아르바이트생만 늘릴 수 있으면 단기예요.\n매장까지 넓힐 수 있으면 장기예요.\n몇 달인지가 아니라 무엇을 바꿀 수 있는지가 기준이에요."}, {"type": "table", "title": "단기와 장기 비교", "columns": ["구분", "고정 생산요소", "논농사 예시"], "rows": [["단기", "있음", "논은 그대로, 사람만 늘림"], ["장기", "없음 (모두 가변)", "사람도 늘리고 논도 늘림"]]}, {"type": "table", "title": "업종마다 다른 장기의 길이", "columns": ["업종", "자본을 늘리는 방법", "장기까지"], "rows": [["콩나물 공장", "키우는 양동이 추가", "아주 짧음"], ["자동차 공장", "공장 새로 짓기", "1~2년"]], "caption": "같은 장기라도 업종마다 걸리는 시간이 달라요."}, {"type": "text", "title": "왜 중요할까?", "body": "비용, 공급곡선, 시장 균형까지 미시경제 이론은 단기와 장기를 나눠서 설명해요.\n이 구분을 먼저 잡아야 뒤의 내용이 쉽게 이어져요."}]'::jsonb,ARRAY['tesat']::text[]),
(1068,'고정 생산요소','생산량을 바꾸려 해도 당장은 늘리거나 줄일 수 없는 생산요소','고정 생산요소는 생산량을 바꾸려 해도 단기에는 양을 조절할 수 없는 생산요소다. 공장, 기계, 토지처럼 한번 들이면 바꾸는 데 시간이 걸리는 자본이 대표적이다. 고정 생산요소가 있는 기간을 단기라고 하며, 이 요소에 드는 돈이 고정비용이 된다.','','ㄱㅈㅅㅅㅇㅅ',ARRAY['가변 생산요소','생산의 단기와 장기','고정비용','수확체감의 법칙']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "1만 평 논에 일할 사람은 금방 더 데려올 수 있어요.\n하지만 논 자체는 당장 늘릴 수 없어요.\n이 논처럼 당장 못 바꾸는 요소가 고정 생산요소예요."}, {"type": "table", "title": "고정 생산요소와 가변 생산요소", "columns": ["구분", "뜻", "예시"], "rows": [["고정 생산요소", "당장은 바꿀 수 없음", "논, 공장, 기계"], ["가변 생산요소", "생산량에 맞춰 바꿀 수 있음", "일하는 사람, 원재료"]], "caption": "단기 모형에서는 보통 자본을 고정, 노동을 가변으로 둬요."}]'::jsonb,ARRAY['tesat']::text[]),
(1069,'가변 생산요소','생산량에 맞춰 바로 늘리거나 줄일 수 있는 생산요소','가변 생산요소는 생산량에 맞춰 단기에도 양을 조절할 수 있는 생산요소다. 고용과 해고로 바꿀 수 있는 노동, 쓰는 만큼 사는 원재료가 대표적이다. 장기에는 공장과 기계까지 바꿀 수 있어 모든 생산요소가 가변이 된다.','','ㄱㅂㅅㅅㅇㅅ',ARRAY['고정 생산요소','생산의 단기와 장기','가변비용','한계생산']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "카페에 손님이 늘면 아르바이트생을 더 뽑고 원두를 더 사요.\n이렇게 생산량에 맞춰 바로 조절하는 요소가 가변 생산요소예요."}, {"type": "flow", "title": "단기에 생산을 늘리는 방법", "steps": ["주문 증가", "가변 생산요소(노동·재료) 추가 투입", "공장은 그대로", "생산량 증가"], "caption": "단기에는 가변 생산요소만으로 생산량을 조절해요."}]'::jsonb,ARRAY['tesat']::text[]),
(1070,'생산함수','생산요소를 얼마나 넣으면 생산량이 얼마나 나오는지 나타낸 식','생산함수는 노동과 자본 같은 생산요소의 투입량과 그것으로 만들 수 있는 최대 생산량의 관계를 나타낸 식이다. 보통 Q = f(L, K)로 쓰며, L은 노동, K는 자본이다. 자본이 고정된 단기 생산함수는 K 위에 막대를 붙여 표시한다.','','ㅅㅅㅎㅅ',ARRAY['생산의 단기와 장기','총생산','한계생산','규모에 대한 수익']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "재료를 넣으면 결과물이 나오는 요리 레시피와 비슷해요.\n일하는 사람과 기계를 얼마나 쓰면 몇 개를 만들 수 있는지 보여줘요."}, {"type": "table", "title": "단기와 장기 생산함수 표기", "columns": ["구분", "표기", "뜻"], "rows": [["단기", "Q = f(L, K) + K 위 막대", "자본은 고정"], ["장기", "Q = f(L, K)", "노동·자본 모두 변수"]], "caption": "K 위에 막대가 있으면 자본이 고정된 단기예요."}]'::jsonb,ARRAY['tesat']::text[]),
(1071,'총생산','생산요소를 투입해 만든 생산량 전체','총생산(TP)은 일정한 생산요소를 투입해 만들어 낸 생산량의 합계다. 단기에 노동을 늘리면 한계생산이 0보다 큰 동안 총생산이 계속 늘어난다. 한계생산이 0이 되는 지점에서 총생산이 가장 크고, 그 뒤로는 오히려 줄어든다.','','ㅊㅅㅅ',ARRAY['평균생산','한계생산','수확체감의 법칙','생산함수']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "논에서 일꾼 다섯 명이 거둔 쌀이 모두 18가마라면 총생산은 18가마예요.\n일꾼을 더 넣을수록 늘다가 어느 순간 멈추고 줄기도 해요."}, {"type": "line", "title": "일꾼 수에 따른 총생산 (논 1만 평)", "unit": "가마", "x": ["1명", "2명", "3명", "4명", "5명", "6명", "7명", "8명", "9명", "10명"], "series": [{"name": "총생산", "values": [2, 5, 9, 14, 18, 21, 23, 24, 24, 23]}], "caption": "9명째에서 한계생산이 0이 되며 총생산이 24가마로 가장 커요.\n10명째부터는 오히려 줄어요."}, {"type": "table", "title": "한계생산과 총생산의 관계", "columns": ["한계생산", "총생산"], "rows": [["0보다 큼", "증가"], ["0", "최대"], ["0보다 작음", "감소"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1072,'평균생산','총생산을 투입한 노동량으로 나눈 1인당 생산량','평균생산(AP)은 총생산을 노동 투입량으로 나눈 값으로 노동자 한 사람이 평균적으로 만든 양이다. 한계생산이 평균생산보다 크면 평균생산이 오르고, 작으면 내려간다. 따라서 한계생산과 평균생산이 같아지는 곳에서 평균생산이 가장 높다.','','ㅍㄱㅅㅅ',ARRAY['총생산','한계생산','노동생산성']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "5명이 쌀 18가마를 거뒀다면 평균생산은 3.6가마예요.\n새로 온 사람이 평균보다 많이 거두면 평균이 오르고, 적게 거두면 내려가요."}, {"type": "table", "title": "한계생산과 평균생산의 관계", "columns": ["관계", "평균생산"], "rows": [["한계생산 > 평균생산", "증가"], ["한계생산 = 평균생산", "최대"], ["한계생산 < 평균생산", "감소"]], "caption": "시험 점수 평균과 같은 원리예요."}]'::jsonb,ARRAY['tesat']::text[]),
(1073,'한계생산','생산요소를 한 단위 더 넣을 때 늘어나는 생산량','한계생산(MP)은 다른 생산요소는 그대로 두고 노동 같은 생산요소를 한 단위 더 투입할 때 늘어나는 생산량이다. 단기에는 처음에 늘다가 어느 순간부터 줄어드는데 이를 수확체감의 법칙이라고 한다. 한계생산이 0보다 크면 총생산은 늘고, 0이면 총생산이 최대가 된다.','','ㅎㄱㅅㅅ',ARRAY['총생산','평균생산','수확체감의 법칙','한계비용']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "\"한 명 더 뽑으면 몇 개 더 나오나\"가 한계생산이에요.\n좁은 주방에 요리사를 계속 늘리면 서로 부딪혀 추가로 나오는 요리가 줄어요."}, {"type": "table", "title": "논농사로 보는 생산 (논 1만 평 고정)", "columns": ["노동", "한계생산", "총생산", "평균생산"], "rows": [["3명", "4가마", "9가마", "3"], ["4명", "5가마", "14가마", "3.5"], ["5명", "4가마", "18가마", "3.6"], ["6명", "3가마", "21가마", "3.5"], ["9명", "0가마", "24가마", "약 2.7"], ["10명", "-1가마", "23가마", "2.3"]], "caption": "5명째부터 한계생산이 줄어요.\n그래도 0보다 크면 총생산은 계속 늘어요."}, {"type": "text", "title": "왜 중요할까?", "body": "기업이 사람을 더 뽑을지 판단하는 기준이 한계생산이에요.\n한계생산이 줄면 하나 더 만드는 비용인 한계비용이 커져요."}]'::jsonb,ARRAY['tesat']::text[]),
(1074,'규모에 대한 수익','모든 생산요소를 같은 비율로 늘릴 때 생산량이 늘어나는 정도','규모에 대한 수익은 장기에 노동과 자본을 모두 같은 비율로 늘릴 때 생산량이 얼마나 늘어나는지를 나타낸다. 생산요소를 2배로 늘렸을 때 생산량이 2배보다 많으면 체증, 딱 2배면 불변, 2배보다 적으면 체감이다. 투입과 생산량의 관계라는 점에서 생산량과 비용의 관계인 규모의 경제와 구분된다.','','ㄱㅁㅇㄷㅎㅅㅇ',ARRAY['규모의 경제','수확체감의 법칙','생산함수','생산의 단기와 장기']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "일꾼도 두 배, 논도 두 배로 늘렸을 때 쌀이 몇 배 나오는지 보는 개념이에요.\n모든 요소를 함께 늘리니 장기에만 따질 수 있어요."}, {"type": "table", "title": "노동·자본을 2배로 늘리면", "columns": ["생산량", "이름"], "rows": [["2배보다 많이", "규모에 대한 수익 체증"], ["딱 2배", "규모에 대한 수익 불변"], ["2배보다 적게", "규모에 대한 수익 체감"]]}, {"type": "table", "title": "헷갈리기 쉬운 개념", "columns": ["개념", "기간", "보는 것"], "rows": [["수확체감의 법칙", "단기", "노동만 늘릴 때 한계생산"], ["규모에 대한 수익", "장기", "모두 늘릴 때 생산량"], ["규모의 경제", "장기", "생산량과 평균비용"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1075,'고정비용','생산량과 상관없이 일정하게 드는 비용','고정비용(TFC)은 생산량이 많든 적든, 심지어 생산하지 않아도 일정하게 나가는 비용이다. 가게 임대료, 기계 리스료처럼 고정 생산요소에 드는 비용이 대표적이다. 모든 생산요소를 바꿀 수 있는 장기에는 고정비용이 없어지고 모든 비용이 가변비용이 된다.','','ㄱㅈㅂㅇ',ARRAY['가변비용','손익분기점','매몰비용','평균고정비용']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "빵을 200개 굽든 300개 굽든 한 달 임대료 100만 원은 그대로예요.\n이렇게 안 만들어도 나가는 돈이 고정비용이에요."}, {"type": "table", "title": "빵집 총비용 (임대료 100만 원, 재료비 개당 1,000원)", "columns": ["생산량", "고정비용", "가변비용", "총비용"], "rows": [["0개", "100만", "0", "100만"], ["200개", "100만", "20만", "120만"], ["500개", "100만", "50만", "150만"], ["1,000개", "100만", "100만", "200만"]], "caption": "생산량이 0이어도 단기에는 100만 원이 나가요."}, {"type": "table", "title": "고정비용과 매몰비용", "columns": ["구분", "고정비용", "매몰비용"], "rows": [["기준", "생산량과 상관없음", "되돌릴 수 없음"], ["예시", "다음 달 임대료", "이미 낸 인테리어비"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1076,'가변비용','생산량이 늘거나 줄면 함께 변하는 비용','가변비용(TVC)은 생산량에 따라 늘어나거나 줄어드는 비용이다. 재료비, 시간제 인건비, 전기료처럼 가변 생산요소에 드는 비용이 여기에 속한다. 총비용은 고정비용과 가변비용의 합이며, 장기에는 모든 비용이 가변비용이다.','','ㄱㅂㅂㅇ',ARRAY['고정비용','손익분기점','한계비용','평균가변비용']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "빵을 많이 구울수록 밀가루 값이 더 들어요.\n이렇게 만들수록 늘어나는 돈이 가변비용이에요."}, {"type": "table", "title": "단기 비용과 장기 비용", "columns": ["구분", "총비용 구성", "이유"], "rows": [["단기", "고정비용 + 가변비용", "설비·계약을 당장 못 바꿈"], ["장기", "가변비용만", "설비를 늘리거나 줄일 수 있음"]]}, {"type": "text", "title": "왜 중요할까?", "body": "공유오피스나 클라우드처럼 고정비를 쓴 만큼 내는 가변비용으로 바꿔주는 서비스가 많아요.\n불황에 버티는 힘이 비용 구조에서 갈려요."}]'::jsonb,ARRAY['tesat']::text[]),
(1077,'이윤','총수입에서 총비용을 빼고 기업에 남는 몫','이윤은 총수입에서 총비용을 뺀 값이고, 총수입은 가격에 판매량을 곱한 값이다. 기업은 이윤을 가장 크게 만드는 생산량을 고르는데, 그 조건이 한계수입과 한계비용이 같아지는 것이다. 경제학의 비용에는 기회비용이 포함되므로 경제적 이윤이 0이어도 정상적인 보상은 받고 있는 상태다.','','ㅇㅇ',ARRAY['손익분기점','한계수입','한계비용','이윤극대화 조건']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "빵을 3,000원에 500개 팔면 총수입은 150만 원이에요.\n총비용이 150만 원이면 이윤은 0, 120만 원이면 30만 원이에요."}, {"type": "table", "title": "빵집 이윤 계산 (임대료 100만 원, 재료비 개당 1,000원, 가격 3,000원)", "columns": ["판매량", "총수입", "총비용", "이윤"], "rows": [["200개", "60만", "120만", "-60만"], ["500개", "150만", "150만", "0"], ["800개", "240만", "180만", "+60만"]], "caption": "이윤이 0이 되는 500개가 손익분기점이에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1078,'단기 비용곡선','고정비용이 있는 단기에 생산량별 비용 변화를 그린 곡선들','단기 비용곡선은 고정 생산요소가 있는 단기에 생산량에 따라 총비용, 평균비용, 한계비용이 어떻게 바뀌는지 그린 곡선이다. 총비용은 계속 늘어나고, 한계비용·평균비용·평균가변비용은 U자 모양을 그린다. 한계비용 곡선은 평균가변비용과 평균비용의 최저점을 아래에서 위로 차례로 지나간다.','','ㄷㄱㅂㅇㄱㅅ',ARRAY['한계비용','평균고정비용','평균가변비용','수확체감의 법칙']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "하나 더 만들 때 드는 돈(한계비용)이 평균보다 낮으면 평균을 끌어내리고, 높으면 끌어올려요.\n그래서 평균비용 곡선이 U자가 돼요."}, {"type": "table", "title": "한계비용과 평균비용의 관계", "columns": ["관계", "평균비용"], "rows": [["한계비용 < 평균비용", "내려가요"], ["한계비용 = 평균비용", "최저점"], ["한계비용 > 평균비용", "올라가요"]], "caption": "최저점 순서는 한계비용 → 평균가변비용 → 평균비용이에요."}, {"type": "flow", "title": "U자 모양이 생기는 이유", "steps": ["처음엔 한계생산 증가", "한계비용 감소", "수확체감으로 한계생산 감소", "한계비용 증가"]}, {"type": "text", "title": "왜 중요할까?", "body": "완전경쟁 기업의 공급곡선, 손익분기점, 조업중단점이 모두 단기 비용곡선에서 나와요."}]'::jsonb,ARRAY['tesat']::text[]),
(1079,'평균고정비용','고정비용을 생산량으로 나눈 값으로, 많이 만들수록 줄어듦','평균고정비용(AFC)은 고정비용을 생산량으로 나눈 값으로 제품 하나에 얹히는 고정비 몫이다. 고정비용은 그대로인데 나누는 생산량이 커지므로 생산량이 늘수록 계속 줄어든다. 평균비용은 평균고정비용과 평균가변비용의 합이다.','','ㅍㄱㄱㅈㅂㅇ',ARRAY['고정비용','평균가변비용','단기 비용곡선','규모의 경제']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "임대료 100만 원을 커피 1,000잔으로 나누면 한 잔에 1,000원이에요.\n4,000잔을 팔면 250원으로 줄어요."}, {"type": "line", "title": "판매량별 잔당 비용 (임대료 100만 원, 재료비 잔당 500원)", "unit": "원", "x": ["500잔", "1,000잔", "2,000잔", "4,000잔"], "series": [{"name": "평균고정비용", "values": [2000, 1000, 500, 250]}, {"name": "평균가변비용", "values": [500, 500, 500, 500]}, {"name": "평균비용", "values": [2500, 1500, 1000, 750]}], "caption": "평균고정비용은 U자가 아니라 계속 줄기만 해요."}]'::jsonb,ARRAY['tesat']::text[]),
(1080,'평균가변비용','가변비용을 생산량으로 나눈 제품 하나당 가변비용','평균가변비용(AVC)은 가변비용을 생산량으로 나눈 값으로 제품 하나당 들어가는 재료비·인건비 같은 비용이다. 단기에는 U자 모양이며 한계비용 곡선이 그 최저점을 지나간다. 완전경쟁 기업은 가격이 평균가변비용 최저점보다 낮아지면 단기에도 생산을 멈춘다.','','ㅍㄱㄱㅂㅂㅇ',ARRAY['평균고정비용','조업중단점','가변비용','단기 비용곡선']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "커피 한 잔에 드는 원두·우유·컵 값이 평균가변비용이에요.\n임대료처럼 안 만들어도 나가는 돈은 빠져 있어요."}, {"type": "table", "title": "평균비용과 평균가변비용", "columns": ["구분", "포함하는 비용", "최저점의 의미"], "rows": [["평균비용", "고정비용 + 가변비용", "손익분기점"], ["평균가변비용", "가변비용만", "조업중단점"]], "caption": "평균가변비용 최저점이 평균비용 최저점보다 왼쪽에 있어요."}]'::jsonb,ARRAY['tesat']::text[]),
(1081,'가격수용자','시장에서 정해진 가격을 그대로 받아들이는 경제주체','가격수용자는 자기 행동으로 시장 가격을 바꿀 수 없어 주어진 가격을 그대로 받아들이는 기업이나 소비자다. 완전경쟁시장의 개별 기업이 대표적이며, 이 기업이 마주하는 수요곡선은 수평이다. 그래서 가격과 한계수입이 같고, 이윤극대화 조건은 가격 = 한계비용이 된다.','','ㄱㄱㅅㅇㅈ',ARRAY['완전경쟁시장','이윤극대화 조건','조업중단점','독점']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "배추 농가 한 곳이 값을 올리면 다들 옆 농가 배추를 사요.\n값을 내릴 이유도 없으니 시세 그대로 팔 수밖에 없어요."}, {"type": "table", "title": "시장 전체와 개별 기업의 수요곡선", "columns": ["구분", "모양", "이유"], "rows": [["시장 전체", "우하향", "값이 내리면 더 사요"], ["개별 기업", "수평", "시장 가격에 얼마든지 팔 수 있어요"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1082,'조업중단점','가격이 평균가변비용 최저점과 같아 생산을 멈출지 갈리는 점','조업중단점은 가격이 평균가변비용의 최저점과 같아지는 점으로, 이보다 가격이 낮으면 단기에도 생산을 멈추는 것이 낫다. 가격이 평균비용보다 낮아 손실이 나도 평균가변비용보다 높으면 고정비 일부를 건질 수 있어 생산을 계속한다. 생산 중단은 고정비가 계속 나가는 단기의 선택이고, 시장을 아예 떠나는 퇴출은 장기의 선택이다.','','ㅈㅇㅈㄷㅈ',ARRAY['손익분기점','평균가변비용','가격수용자','고정비용']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "적자라도 재료비와 인건비를 건지면 문을 여는 게 손해가 적어요.\n재료비조차 못 건지면 그때 문을 닫아요."}, {"type": "table", "title": "가격에 따른 단기 선택", "columns": ["가격 수준", "상태", "선택"], "rows": [["평균비용 최저점보다 높음", "이윤", "생산"], ["평균비용과 평균가변비용 사이", "손실이지만 고정비 일부 회수", "생산 계속"], ["평균가변비용 최저점보다 낮음", "가변비용도 못 건짐", "생산 중단"]]}, {"type": "table", "title": "커피 가게 예시 (임대료 100만 원, 재료비 잔당 2,000원, 월 1,000잔)", "columns": ["선택", "이번 달 손실"], "rows": [["가격 2,500원에 영업", "50만 원"], ["문 닫기", "100만 원 (임대료)"]], "caption": "잔당 500원씩 임대료를 메울 수 있어 영업이 나아요."}]'::jsonb,ARRAY['tesat']::text[]),
(1083,'이윤극대화 조건','한계수입과 한계비용이 같아지는 곳에서 생산량을 정하는 원칙','이윤극대화 조건은 하나 더 팔 때 늘어나는 수입(한계수입)과 하나 더 만들 때 드는 비용(한계비용)이 같아지도록 생산량을 정하는 것이다. 한계수입이 한계비용보다 크면 더 만들고, 작으면 줄이는 것이 이윤을 늘린다. 완전경쟁에서는 가격과 한계수입이 같아 가격 = 한계비용이 되고, 독점은 한계수입이 가격보다 낮다.','','ㅇㅇㄱㄷㅎㅈㄱ',ARRAY['한계수입','한계비용','이윤','가격수용자']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "하나 더 팔아 버는 돈이 하나 더 만드는 비용보다 크면 더 만들어요.\n둘이 같아지는 순간이 이윤이 가장 큰 지점이에요."}, {"type": "table", "title": "사탕 하나 100원일 때 생산량 고르기", "columns": ["생산량", "한계비용", "이윤"], "rows": [["7개", "70원", "400원"], ["8개", "90원", "410원"], ["9개", "100원", "410원"], ["10개", "130원", "380원"]], "caption": "한계비용이 가격 100원에 닿는 9개까지 만들면 이윤이 가장 커요."}, {"type": "table", "title": "시장별 이윤극대화", "columns": ["시장", "조건"], "rows": [["모든 시장", "한계수입 = 한계비용"], ["완전경쟁", "가격 = 한계비용"], ["독점", "한계수입 = 한계비용, 가격은 수요곡선에서"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1084,'진입장벽','새 기업이 시장에 들어오기 어렵게 만드는 요인','진입장벽은 새로운 기업이 시장에 들어오는 것을 어렵게 만드는 요인이다. 규모의 경제, 특허나 면허 같은 법적 장치, 원료 독점, 막대한 초기 투자비 등이 해당한다. 진입장벽이 높으면 기존 기업이 장기에도 초과 이윤을 유지할 수 있다.','','ㅈㅇㅈㅂ',ARRAY['독점','자연독점','과점','지대 추구']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "수도·전기처럼 망을 까는 데 큰돈이 들면 새 회사가 들어오기 어려워요.\n이렇게 신규 진입을 막는 벽이 진입장벽이에요."}, {"type": "table", "title": "진입장벽의 종류", "columns": ["종류", "예시"], "rows": [["규모의 경제", "수도, 전기, 가스"], ["법적 장치", "특허, 면허, 인허가"], ["핵심 자원 독점", "원료 산지 보유"], ["큰 초기 비용", "대규모 설비 투자"]]}, {"type": "table", "title": "진입장벽과 장기 초과 이윤", "columns": ["시장", "진입장벽", "장기 초과 이윤"], "rows": [["완전경쟁", "없음", "0"], ["독점적 경쟁", "거의 없음", "0"], ["과점", "높음", "가능"], ["독점", "매우 높음", "가능"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1085,'X비효율성','경쟁 압력이 없어 비용 절감과 혁신을 게을리하는 독점의 비효율','X비효율성은 경쟁이 없는 독점기업이 비용을 줄이거나 기술을 개발하려는 노력을 게을리해 생기는 비효율이다. 같은 양을 만들 수 있는 최소 비용보다 실제 비용이 더 높아지는 문제다. 덜 만들어서 생기는 후생손실과 별개로 독점을 비판하는 근거가 된다.','','Xㅂㅎㅇㅅ',ARRAY['독점','슘페터 가설','진입장벽','불완전경쟁시장']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "손님이 어차피 우리 가게밖에 갈 데가 없다면 굳이 비용을 아끼거나 서비스를 개선할 필요를 덜 느껴요.\n이런 느슨함이 X비효율성이에요."}, {"type": "table", "title": "독점과 혁신을 둘러싼 두 주장", "columns": ["주장", "내용"], "rows": [["X비효율성", "경쟁이 없어 비용 절감·기술 개발을 게을리함"], ["슘페터 가설", "초과 이윤으로 연구개발에 투자해 혁신을 이끔"]], "caption": "어느 쪽이 맞는지는 아직 결론이 나지 않았어요."}]'::jsonb,ARRAY['tesat']::text[]),
(1086,'슘페터 가설','독점기업의 초과 이윤이 연구개발과 혁신을 이끈다는 주장','슘페터 가설은 큰 기업이나 독점기업이 초과 이윤을 연구개발에 투자해 기술 혁신을 이끈다는 주장이다. 독점이 생산량을 줄여 비효율적이라는 비판에 맞서 독점의 긍정적인 면을 강조한다. 경쟁이 없어 혁신을 게을리한다는 X비효율성 주장과 대립한다.','','ㅅㅍㅌㄱㅅ',ARRAY['X비효율성','독점','연구개발(R&D)','진입장벽']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "큰돈을 버는 기업일수록 몇 년 걸리는 연구에 투자할 여유가 있어요.\n그래서 독점이 오히려 혁신을 낳을 수 있다는 생각이에요."}, {"type": "text", "title": "왜 중요할까?", "body": "신약 특허처럼 일정 기간 독점을 허용해 연구개발을 유도하는 제도가 이 논리와 닿아 있어요."}]'::jsonb,ARRAY['tesat']::text[]),
(1087,'종량세','물건 한 단위를 팔 때마다 일정액씩 매기는 세금','종량세는 판매량이나 생산량 한 단위마다 정해진 금액을 매기는 세금이다. 기업의 한계비용을 높이므로 생산량이 줄고 가격이 오른다. 독점기업에 종량세를 매기면 가격은 더 오르고 생산량은 더 줄어 후생손실이 커질 수 있다.','','ㅈㄹㅅ',ARRAY['정액세','간접세','조세 귀착','독점']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "라면 한 봉지 팔 때마다 50원씩 세금을 내야 한다면 많이 팔수록 세금도 늘어요.\n그만큼 하나 더 만드는 비용이 올라가요."}, {"type": "table", "title": "종량세와 정액세 비교", "columns": ["구분", "매기는 방식", "한계비용", "생산량·가격"], "rows": [["종량세", "한 단위마다 일정액", "오름", "생산량 감소, 가격 상승"], ["정액세", "생산량과 무관하게 일정액", "그대로", "변화 없음"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1088,'정액세','생산량과 상관없이 정해진 금액을 한 번에 매기는 세금','정액세는 생산량이나 판매량과 관계없이 일정한 금액을 부과하는 세금이다. 고정비용처럼 작용해 한계비용을 바꾸지 않으므로 이윤극대화 생산량과 가격이 그대로다. 독점기업에 정액세를 매기면 생산량을 왜곡하지 않고 초과 이윤의 일부만 거둘 수 있다.','','ㅈㅇㅅ',ARRAY['종량세','고정비용','조세 귀착','독점']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "많이 팔든 적게 팔든 1년에 100만 원만 내는 세금이에요.\n하나 더 만드는 비용은 그대로라 생산량도 가격도 바뀌지 않아요."}, {"type": "text", "title": "왜 중요할까?", "body": "세금이 경제활동을 덜 왜곡하려면 한계비용을 건드리지 않는 방식이 유리해요.\n그래서 정액세는 효율적인 세금의 기준으로 자주 쓰여요."}]'::jsonb,ARRAY['tesat']::text[]),
(1089,'우월전략','상대가 어떤 전략을 고르든 자신에게 가장 유리한 전략','우월전략은 상대가 무엇을 선택하든 상관없이 나에게 늘 더 좋은 결과를 주는 전략이다. 모든 경기자에게 우월전략이 있으면 그 조합이 우월전략 균형이 된다. 우월전략이 없는 경기자도 있어 모든 게임에 우월전략이 존재하지는 않는다.','','ㅇㅇㅈㄹ',ARRAY['우월전략 균형','보수표','내쉬균형','죄수의 딜레마']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "상대가 증산하든 감산하든 나는 증산하는 게 늘 낫다면 증산이 우월전략이에요.\n상대 눈치를 볼 필요가 없는 전략이에요."}, {"type": "table", "title": "A 기업의 보수표 (앞 숫자 A, 뒤 숫자 B 이윤, 단위 억 원)", "columns": ["A \\ B", "B 증산", "B 감산"], "rows": [["A 증산", "12, 12", "23, 5"], ["A 감산", "5, 23", "15, 15"]], "caption": "B가 증산하면 12 > 5, 감산해도 23 > 15라 A는 늘 증산이 나아요."}]'::jsonb,ARRAY['tesat']::text[]),
(1090,'우월전략 균형','모든 경기자가 각자 우월전략을 골라 이루어진 균형','우월전략 균형은 모든 경기자에게 우월전략이 있고 각자 그 전략을 선택했을 때의 결과다. 우월전략 균형은 항상 내쉬균형이지만 내쉬균형이 모두 우월전략 균형인 것은 아니다. 죄수의 딜레마처럼 우월전략 균형이 모두에게 최선의 결과가 아닐 수 있다.','','ㅇㅇㅈㄹㄱㅎ',ARRAY['우월전략','내쉬균형','죄수의 딜레마','게임이론']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "두 기업 모두 상대와 상관없이 증산이 낫다면 (증산, 증산)에서 멈춰요.\n둘 다 감산하면 더 벌 수 있는데도 그 자리를 못 떠나요."}, {"type": "table", "title": "우월전략 균형과 내쉬균형", "columns": ["구분", "우월전략 균형", "내쉬균형"], "rows": [["조건", "모두에게 우월전략이 있음", "서로 최선 대응이면 됨"], ["개수", "있으면 하나", "0개, 1개, 여러 개"], ["관계", "항상 내쉬균형", "우월전략 균형이 아닐 수 있음"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1091,'반복 게임','같은 상대와 같은 게임을 여러 번 되풀이하는 상황','반복 게임은 같은 경기자들이 같은 게임을 여러 번 되풀이하는 상황이다. 한 번뿐인 게임에서는 배신이 유리해도 반복되면 배신에 보복할 수 있어 협조가 유지되기 쉽다. 과점 기업의 담합이 오래가는 이유를 설명할 때 쓰인다.','','ㅂㅂㄱㅇ',ARRAY['죄수의 딜레마','카르텔','게임이론','우월전략']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "한 번 보고 말 사이면 배신해도 그만이지만, 매일 볼 사이면 다음에 보복당할까 봐 약속을 지켜요."}, {"type": "table", "title": "한 번과 반복의 차이", "columns": ["구분", "배신의 결과", "협조"], "rows": [["한 번뿐인 게임", "당장 이득", "깨지기 쉬움"], ["반복 게임", "다음 판에 보복당함", "유지되기도 함"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1092,'가격 선도','큰 기업이 가격을 정하면 나머지 기업이 따라가는 과점의 행태','가격 선도는 과점시장에서 시장 점유율이 큰 기업이 먼저 가격을 정하거나 바꾸면 다른 기업들이 이를 따르는 행태다. 명시적인 합의 없이도 가격이 비슷하게 움직여 담합과 비슷한 결과가 나올 수 있다. 이 때문에 경쟁당국은 가격이 함께 움직이는 과점 시장을 주의 깊게 살핀다.','','ㄱㄱㅅㄷ',ARRAY['과점','카르텔','반복 게임','시장 구조']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "업계 1위가 값을 올리면 며칠 뒤 다른 회사들도 비슷하게 올려요.\n앞장선 회사를 따라가는 모습이라 가격 선도라고 해요."}, {"type": "flow", "title": "가격 선도가 일어나는 흐름", "steps": ["선도 기업이 가격 인상", "다른 기업이 반응을 살핌", "비슷한 폭으로 따라 인상", "시장 가격이 함께 오름"]}]'::jsonb,ARRAY['tesat']::text[]),
(1093,'보수표','경기자들의 전략 조합별로 각자 얻는 결과를 정리한 표','보수표는 게임이론에서 경기자들이 고를 수 있는 전략의 조합마다 각자가 얻는 보수(이윤, 효용 등)를 정리한 표다. 칸 안의 앞 숫자는 행 경기자, 뒤 숫자는 열 경기자의 보수다. 상대 전략별 내 최선에 밑줄을 그어 두 경기자 모두 밑줄인 칸을 찾으면 내쉬균형이 된다.','','ㅂㅅㅍ',ARRAY['게임이론','우월전략','내쉬균형','죄수의 딜레마']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "\"상대가 이러면 나는 얼마, 저러면 얼마\"를 한눈에 보는 표예요.\n최선 대응에 밑줄을 그어 보면 균형이 보여요."}, {"type": "table", "title": "담합 보수표 (앞 숫자 A, 뒤 숫자 B, 단위 억 원)", "columns": ["A \\ B", "B 저가", "B 고가"], "rows": [["A 저가", "30, 30", "150, 10"], ["A 고가", "10, 150", "100, 100"]], "caption": "혼자 싸게 팔면 150억이라 저가가 우월전략이에요.\n그래서 담합은 안에서부터 깨지기 쉬워요."}, {"type": "flow", "title": "밑줄로 균형 찾기", "steps": ["상대 전략별 내 최선에 밑줄", "내 전략별 상대 최선에 밑줄", "둘 다 밑줄인 칸 = 내쉬균형"]}]'::jsonb,ARRAY['tesat']::text[]),
(1094,'상품 차별화','맛·품질·디자인·서비스 등으로 다른 기업 제품과 차이를 두는 것','상품 차별화는 같은 종류의 상품이라도 품질, 디자인, 브랜드, 서비스 등에서 다른 기업 제품과 차이를 만드는 것이다. 차별화가 클수록 대체재가 적어져 수요곡선이 가팔라지고 가격 결정력이 커진다. 독점적 경쟁시장 기업이 작은 독점력을 갖는 원천이다.','','ㅅㅍㅊㅂㅎ',ARRAY['독점적 경쟁','비가격 경쟁','수요탄력성','시장 구조']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "실력 좋은 미용실은 옆 가게보다 조금 비싸도 단골이 계속 찾아와요.\n이렇게 남과 다르게 만드는 게 상품 차별화예요."}, {"type": "table", "title": "차별화 정도와 가격 결정력", "columns": ["차별화", "대체재", "수요곡선", "가격 결정력"], "rows": [["작음", "많음", "완만함 (탄력적)", "약함"], ["큼", "적음", "가파름 (비탄력적)", "강함"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1095,'비가격 경쟁','가격 대신 광고·품질·서비스 등으로 손님을 끄는 경쟁','비가격 경쟁은 가격을 내리는 대신 광고, 디자인, 품질, 서비스, 브랜드 등으로 소비자를 끌어오는 경쟁이다. 과점시장에서 특히 치열하고, 독점적 경쟁시장에서도 흔하다. 가격 경쟁은 서로 손해를 보기 쉬워 기업들이 다른 방식으로 경쟁하는 것이다.','','ㅂㄱㄱㄱㅈ',ARRAY['상품 차별화','과점','독점적 경쟁','시장 구조']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "통신사들이 요금은 비슷하게 두고 멤버십 혜택과 광고로 경쟁하는 모습이 비가격 경쟁이에요."}, {"type": "table", "title": "시장별 비가격 경쟁", "columns": ["시장", "비가격 경쟁"], "rows": [["완전경쟁", "거의 없음 (상품이 같음)"], ["독점적 경쟁", "많음 (인테리어, 서비스)"], ["과점", "매우 치열 (광고, 디자인)"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1096,'시장 구조','기업 수·상품 동질성·진입 난이도로 나눈 시장의 형태','시장 구조는 공급하는 기업의 수, 상품이 같은지 다른지, 진입이 쉬운지에 따라 시장을 나눈 것이다. 보통 완전경쟁, 독점적 경쟁, 과점, 독점의 네 가지로 구분한다. 시장 구조에 따라 기업의 가격 결정력, 장기 이윤, 효율성이 달라진다.','','ㅅㅈㄱㅈ',ARRAY['완전경쟁시장','독점적 경쟁','과점','독점']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "파는 기업이 몇 곳인지, 파는 물건이 서로 같은지, 새로 들어오기 쉬운지를 보면 시장을 네 가지로 나눌 수 있어요."}, {"type": "table", "title": "시장 구조 4가지", "columns": ["구분", "기업 수", "상품", "진입장벽", "장기 초과 이윤"], "rows": [["완전경쟁", "무수히 많음", "동질", "없음", "0"], ["독점적 경쟁", "많음", "차별화", "거의 없음", "0"], ["과점", "소수", "동질·차별", "높음", "가능"], ["독점", "하나", "대체재 없음", "매우 높음", "가능"]], "caption": "가격 = 한계비용으로 효율적인 건 완전경쟁뿐이에요."}, {"type": "text", "title": "왜 중요할까?", "body": "공정거래 정책은 시장 구조를 보고 경쟁이 충분한지 판단하는 데서 출발해요."}]'::jsonb,ARRAY['tesat']::text[]),
(1097,'과잉설비','장기 균형에서 평균비용 최저점보다 적게 생산해 남는 설비 여유','과잉설비는 독점적 경쟁시장의 장기 균형에서 기업이 평균비용이 가장 낮아지는 생산량보다 적게 생산해 설비에 여유가 남는 현상이다. 장기에는 수요곡선이 평균비용 곡선에 접하는 점에서 이윤이 0이 되는데, 그 점이 평균비용 최저점보다 왼쪽에 있기 때문이다. 가격이 한계비용보다 높아 완전경쟁보다 덜 효율적이라는 뜻이기도 하다.','','ㄱㅇㅅㅂ',ARRAY['독점적 경쟁','상품 차별화','완전경쟁시장','규모의 경제']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "동네마다 카페가 많으면 가게마다 좌석이 남아도는 시간이 많아요.\n더 받을 수 있는 설비를 놀리는 셈이라 과잉설비라고 해요."}, {"type": "table", "title": "독점적 경쟁의 장기 균형", "columns": ["조건", "뜻"], "rows": [["가격 = 평균비용", "초과 이윤 0"], ["한계수입 = 한계비용", "이윤 극대화는 그대로"], ["가격 > 한계비용", "완전경쟁보다 적게 생산"], ["평균비용 최저점보다 왼쪽", "설비에 여유가 남음"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1098,'지대','토지처럼 공급이 고정된 생산요소를 쓰는 대가','지대는 원래 토지를 사용하는 대가로, 노동의 임금·자본의 이자와 함께 생산요소의 소득이다. 토지는 공급이 고정돼 공급곡선이 수직이어서 땅값은 수요에 따라 정해진다. 오늘날에는 토지뿐 아니라 공급이 고정된 모든 생산요소가 받는 보수를 넓게 지대라고 부른다.','','ㅈㄷ',ARRAY['경제적 지대','차액지대','준지대','절대지대']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "일한 대가는 임금, 돈을 빌려준 대가는 이자, 땅을 빌려준 대가가 지대예요.\n땅은 더 만들 수 없어서 수요가 늘면 값이 그대로 올라요."}, {"type": "table", "title": "생산요소와 그 대가", "columns": ["생산요소", "대가"], "rows": [["노동", "임금"], ["자본", "이자"], ["토지", "지대"]]}, {"type": "table", "title": "지대를 보는 두 관점", "columns": ["관점", "지대의 성격", "이유"], "rows": [["고전학파", "불로소득", "토지 공급은 고정, 지대는 수요가 정함"], ["신고전학파", "비용", "토지도 다른 용도가 있어 기회비용을 내야 함"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1099,'차액지대','비옥한 땅이 한계지보다 더 거둔 수확량만큼 받는 대가','차액지대는 리카도가 제시한 개념으로, 비옥한 땅이 경작되는 마지막 땅인 한계지보다 더 거둔 수확량이 지대가 된다는 것이다. 한계지는 비용만 겨우 건지므로 지대가 0이다. 리카도는 곡물 값이 비싸서 지대가 오르는 것이지 지대 때문에 곡물 값이 오르는 것이 아니라고 보았다.','','ㅊㅇㅈㄷ',ARRAY['지대','절대지대','경제적 지대','수확체감의 법칙']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "같은 노력으로 A 땅은 10가마, 한계지는 5가마를 거두면 A 땅 주인은 차이 5가마만큼 지대를 받을 수 있어요."}, {"type": "table", "title": "리카도의 땅별 차액지대", "columns": ["땅", "수확량", "차액지대"], "rows": [["A", "10가마", "5가마"], ["B", "9가마", "4가마"], ["C", "8가마", "3가마"], ["E", "6가마", "1가마"], ["F (한계지)", "5가마", "0"]], "caption": "비옥할수록 차액지대가 커져요."}]'::jsonb,ARRAY['tesat']::text[]),
(1100,'이전수입','생산요소가 지금 용도에 머물게 하는 데 필요한 최소 보수','이전수입(전용수입)은 생산요소가 다른 용도로 옮겨 가지 않도록 하기 위해 지급해야 하는 최소한의 금액이다. 그 생산요소의 기회비용과 같다. 생산요소가 실제로 받은 총보수에서 이전수입을 뺀 나머지가 경제적 지대다.','','ㅇㅈㅅㅇ',ARRAY['경제적 지대','기회비용','생산자잉여','공급탄력성']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "월급이 180만 원보다 적으면 다른 회사로 옮길 사람이라면 이전수입은 180만 원이에요.\n200만 원을 받는다면 나머지 20만 원은 경제적 지대예요."}, {"type": "table", "title": "공급곡선 모양과 이전수입", "columns": ["공급곡선", "이전수입", "경제적 지대"], "rows": [["완전 탄력적 (수평)", "총수입 전부", "0"], ["우상향", "일부", "일부"], ["완전 비탄력적 (수직)", "0", "총수입 전부"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1101,'지대 추구','새 가치를 만들기보다 로비·진입 제한으로 이익을 얻으려는 행위','지대 추구는 경제적 지대를 얻거나 지키기 위해 생산적인 경쟁 대신 로비, 규제 요구, 진입 제한 등에 자원을 쓰는 행위다. 여기에 쓰인 돈과 시간은 새로운 것을 만들지 않으므로 사회 전체로는 낭비가 된다. 이익집단의 로비가 정부 실패로 이어지는 원인으로도 꼽힌다.','','ㅈㄷㅊㄱ',ARRAY['경제적 지대','진입장벽','정부실패','공공선택이론']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "더 좋은 제품을 만드는 대신 \"경쟁자가 못 들어오게 규제해 달라\"고 로비하는 게 지대 추구예요.\n파이를 키우지 않고 나눠 먹기만 하는 경쟁이에요."}, {"type": "flow", "title": "지대 추구가 낭비가 되는 흐름", "steps": ["이익집단의 로비", "진입 제한 규제", "기존 사업자 초과 이윤 유지", "로비 비용과 후생손실 발생"]}, {"type": "text", "title": "왜 중요할까?", "body": "면허·인허가 같은 규제를 평가할 때 지대 추구의 관점에서 누가 이익을 보는지 따져봐요."}]'::jsonb,ARRAY['tesat']::text[]),
(1102,'준지대','단기에 공급이 고정된 기계·설비 같은 생산요소가 받는 보수','준지대는 단기에는 늘리거나 줄일 수 없는 기계·설비 같은 고정 생산요소가 받는 보수다. 단기에는 토지처럼 공급이 고정돼 지대와 비슷한 성격을 갖지만, 장기에는 설비를 늘릴 수 있어 사라진다. 영구히 고정된 토지의 대가인 지대와 구분된다.','','ㅈㅈㄷ',ARRAY['지대','고정 생산요소','경제적 지대','생산의 단기와 장기']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "수요가 갑자기 늘면 이미 공장을 가진 회사가 한동안 큰돈을 벌어요.\n새 공장이 지어지면 그 몫은 사라져요. 이 일시적인 몫이 준지대예요."}, {"type": "table", "title": "지대와 준지대", "columns": ["구분", "고정된 기간", "장기에는"], "rows": [["지대", "영구히 (토지)", "그대로"], ["준지대", "단기에만 (기계·설비)", "사라짐"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1103,'절대지대','토지 소유권 자체 때문에 한계지에서도 생기는 지대','절대지대는 마르크스가 제시한 개념으로, 토지가 사적으로 소유되어 있다는 사실 자체 때문에 생기는 지대다. 리카도는 가장 나쁜 땅인 한계지의 지대가 0이라고 보았지만, 절대지대설에서는 한계지도 지대를 받는다. 지대의 원인을 비옥도 차이가 아니라 소유권에서 찾는다는 점이 차액지대와 다르다.','','ㅈㄷㅈㄷ',ARRAY['차액지대','지대','경제적 지대']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "아무리 척박한 땅이라도 주인이 공짜로 빌려주지는 않아요.\n이렇게 소유권 때문에 내야 하는 몫이 절대지대예요."}, {"type": "table", "title": "지대 이론 비교", "columns": ["이론", "지대의 원인", "한계지의 지대"], "rows": [["리카도 차액지대설", "비옥도 차이", "0"], ["마르크스 절대지대설", "토지 소유권 자체", "있음"], ["튀넨 입지론", "시장과의 거리", "-"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1104,'10분위분배율','하위 40% 소득을 상위 20% 소득으로 나눈 분배 지표','10분위분배율은 소득 하위 40% 계층의 소득 합을 상위 20% 계층의 소득 합으로 나눈 값이다. 0에서 2 사이 값을 가지며, 다른 분배 지표와 달리 클수록 소득분배가 평등하다. 중간 40% 계층은 계산에 들어가지 않아 중산층의 사정은 잘 보여주지 못한다.','','1ㅂㅇㅂㅂㅇ',ARRAY['지니계수','로렌츠곡선','소득5분위배율']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "모두 똑같이 벌면 하위 40%가 40%, 상위 20%가 20%를 가져 값이 2예요.\n상위 20%가 다 가지면 0이 돼요."}, {"type": "table", "title": "소득분배 지표 비교", "columns": ["지표", "계산", "범위", "평등할수록"], "rows": [["지니계수", "로렌츠 곡선 면적 비율", "0 ~ 1", "작아짐"], ["10분위분배율", "하위 40% ÷ 상위 20%", "0 ~ 2", "커짐"], ["소득5분위배율", "상위 20% ÷ 하위 20%", "1 이상", "작아짐"]], "caption": "세 지표 중 10분위분배율만 클수록 평등해요."}, {"type": "text", "title": "왜 중요할까?", "body": "시험에서는 \"어떤 지표가 클수록 평등한가\"를 가장 자주 물어요.\n지표마다 방향이 달라 여러 지표를 함께 봐야 해요."}]'::jsonb,ARRAY['tesat']::text[]),
(1105,'파레토 개선','누구도 손해 보지 않으면서 적어도 한 명이 더 좋아지는 변화','파레토 개선은 어떤 사람의 효용도 줄이지 않으면서 적어도 한 사람의 효용을 높이는 자원 배분의 변화다. 단 한 명이라도 손해를 보면 파레토 개선이 아니다. 더 이상 파레토 개선이 불가능한 상태를 파레토최적이라고 한다.','','ㅍㄹㅌㄱㅅ',ARRAY['파레토최적','후생경제학','효율성과 형평성','비용편익분석']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "안 쓰는 물건을 필요한 사람에게 팔면 파는 사람도 사는 사람도 좋아져요.\n아무도 손해 보지 않았으니 파레토 개선이에요."}, {"type": "table", "title": "세 사람의 효용 변화", "columns": ["사람", "상태 A", "상태 B"], "rows": [["갑", "100", "100"], ["을", "92", "92"], ["병", "80", "85"]], "caption": "병만 좋아지고 아무도 손해 보지 않아 A → B는 파레토 개선이에요.\n병이 75로 줄었다면 파레토 개선이 아니에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1106,'후생경제학','자원 배분이 사회 전체 후생 측면에서 바람직한지 평가하는 분야','후생경제학은 자원 배분과 경제 상태가 사회 구성원 전체의 후생 측면에서 얼마나 바람직한지를 평가하는 경제학 분야다. 파레토 효율을 기준으로 효율성을 따지고, 어느 효율적 배분이 더 좋은지는 사회후생함수 같은 가치판단에 맡긴다. 외부효과가 없으면 완전경쟁시장 균형이 파레토 효율이라는 후생경제학의 제1정리가 대표적인 결론이다.','','ㅎㅅㄱㅈㅎ',ARRAY['파레토최적','파레토 개선','효율성과 형평성','시장실패']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "경제가 \"잘 돌아간다\"는 게 무슨 뜻인지 따지는 분야예요.\n낭비 없이 쓰였는지와 공평하게 나뉘었는지를 나눠서 봐요."}, {"type": "flow", "title": "후생경제학의 판단 순서", "steps": ["파레토 개선이 남았는지 확인", "남지 않으면 파레토 효율", "여러 효율점 중 선택", "사회후생함수(가치판단)로 결정"]}, {"type": "table", "title": "소비·생산·종합 효율", "columns": ["구분", "조건"], "rows": [["소비(교환)의 효율", "두 사람의 한계대체율이 같음"], ["생산의 효율", "두 재화의 한계기술대체율이 같음"], ["종합 효율", "한계대체율 = 한계변환율"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1107,'효율성과 형평성','자원을 낭비 없이 쓰는지와 공평하게 나누는지를 가르는 두 기준','효율성은 자원이 낭비 없이 쓰였는지, 형평성은 그 결과가 공평하게 나뉘었는지를 묻는 기준이다. 효율성은 파레토 효율처럼 비교적 명확히 판단할 수 있지만 형평성은 가치판단이라 사람마다 기준이 다르다. 두 기준은 서로 부딪히기도 해서 정책은 둘 사이의 균형을 찾아야 한다.','','ㅎㅇㅅㄱㅎㅍㅅ',ARRAY['파레토최적','후생경제학','지니계수','시장실패']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "사과 10개를 한 사람이 다 가져도 남김없이 썼으니 효율적이에요.\n하지만 공평하지는 않아요. 효율과 형평은 다른 질문이에요."}, {"type": "table", "title": "효율성과 형평성 비교", "columns": ["기준", "묻는 것", "측정"], "rows": [["효율성", "낭비 없이 쓰였나?", "비교적 명확"], ["형평성", "공평하게 나뉘었나?", "가치판단이라 사람마다 다름"]]}, {"type": "table", "title": "사과 10개 나누기", "columns": ["배분 (갑·을·병)", "효율?", "공평?"], "rows": [["4·3·3", "효율", "비교적 공평"], ["10·0·0", "효율", "불공평"], ["3·3·3 (1개 버림)", "비효율", "공평"]], "caption": "시장 실패는 효율의 문제, 소득 불평등은 형평의 문제예요."}]'::jsonb,ARRAY['tesat']::text[]),
(1108,'계약곡선','두 사람의 한계대체율이 같아지는 효율적 배분점들을 이은 선','계약곡선은 두 사람이 두 재화를 나눠 가질 때 더 이상 둘 다 좋아지는 교환이 없는 배분점, 즉 소비의 파레토 효율점을 모두 이은 선이다. 이 선 위에서는 두 사람의 한계대체율이 같다. 계약곡선 위의 점은 모두 효율적이지만 어느 점이 공평한지는 알려주지 않는다.','','ㄱㅇㄱㅅ',ARRAY['효용가능곡선','파레토최적','무차별곡선','파레토 개선']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "갑은 밥만, 을은 국만 10그릇 가졌다면 바꿔 먹으면 둘 다 좋아져요.\n교환을 계속해 더는 둘 다 좋아질 수 없는 지점들을 이으면 계약곡선이에요."}, {"type": "flow", "title": "계약곡선에 도달하는 과정", "steps": ["한쪽에 치우친 배분", "서로 이득인 교환", "한계대체율이 같아짐", "계약곡선 위 효율점"]}, {"type": "table", "title": "계약곡선과 효용가능곡선", "columns": ["구분", "그리는 공간", "보여주는 것"], "rows": [["계약곡선", "재화의 양", "효율적인 재화 배분"], ["효용가능곡선", "두 사람의 효용", "효율적인 효용 조합"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1109,'효용가능곡선','자원을 효율적으로 나눌 때 두 사람이 얻을 수 있는 효용 조합을 그린 선','효용가능곡선은 주어진 자원을 효율적으로 배분할 때 두 사람이 동시에 얻을 수 있는 최대 효용의 조합을 그린 곡선이다. 계약곡선 위의 각 배분점을 효용 공간으로 옮겨 그린 것이다. 곡선 위의 점은 모두 파레토 효율이며, 그중 어느 점을 고를지는 사회후생함수가 정한다.','','ㅎㅇㄱㄴㄱㅅ',ARRAY['계약곡선','파레토최적','후생경제학','생산가능곡선']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "한 사람의 만족을 더 높이려면 다른 사람의 만족을 줄여야 하는 경계선이에요.\n생산가능곡선을 효용으로 바꿔 그린 것과 비슷해요."}, {"type": "table", "title": "곡선의 안쪽과 위", "columns": ["위치", "뜻"], "rows": [["곡선 안쪽", "둘 다 좋아질 여지가 있음 (비효율)"], ["곡선 위", "파레토 효율"], ["곡선 바깥", "현재 자원으로는 불가능"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1110,'피구세','부정적 외부효과를 일으키는 활동에 외부 비용만큼 매기는 세금','피구세는 오염처럼 제3자에게 피해를 주는 활동에 그 외부 한계비용만큼 세금을 매기는 것이다. 세금으로 사회적 비용을 생산자의 계산 안에 넣어 과다 생산을 사회적 최적 수준으로 줄인다. 이를 외부효과의 내부화라고 하며, 경제학자 피구의 이름을 땄다.','','ㅍㄱㅅ',ARRAY['외부효과','코즈의 정리','탄소배출권','죄악세']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "가구 공장이 하나 만들 때 이웃에게 10원어치 피해를 준다면 하나당 10원을 세금으로 내게 해요.\n그러면 공장이 피해까지 계산해서 덜 만들어요."}, {"type": "table", "title": "외부효과를 줄이는 방법", "columns": ["방법", "내용", "특징"], "rows": [["피구세", "외부 한계비용만큼 세금", "부정적 외부효과를 줄임"], ["보조금", "외부 한계편익만큼 지원", "긍정적 외부효과를 늘림"], ["직접 규제", "배출량을 직접 제한", "감시 비용이 큼"], ["배출권 거래", "총량을 정하고 사고팔게 함", "시장 원리로 효율적"]]}, {"type": "flow", "title": "피구세가 작동하는 흐름", "steps": ["외부 비용이 가격에 빠짐", "과다 생산", "외부 비용만큼 세금 부과", "사회적 최적 생산량으로 감소"]}]'::jsonb,ARRAY['tesat']::text[]),
(1111,'거래비용','거래 상대를 찾고 협상하고 계약을 지키게 하는 데 드는 비용','거래비용은 시장에서 거래를 할 때 상대를 찾고, 정보를 모으고, 협상하고, 계약 이행을 감시하는 데 드는 비용이다. 코즈의 정리는 재산권이 분명하고 거래비용이 작을 때만 당사자 협상으로 외부효과가 해결된다고 본다. 피해자가 수백만 명인 대기오염처럼 거래비용이 크면 협상이 어려워 정부 개입이 필요해진다.','','ㄱㄹㅂㅇ',ARRAY['코즈의 정리','외부효과','피구세','시장실패']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "중고 거래에서 믿을 만한 상대를 찾고 가격을 흥정하는 데 드는 시간과 수고도 거래비용이에요.\n이 비용이 크면 이득이 되는 거래도 안 일어나요."}, {"type": "table", "title": "거래비용과 해결 방식", "columns": ["상황", "거래비용", "해결"], "rows": [["당사자 두 명, 권리 분명", "작음", "협상 (코즈의 정리)"], ["피해자 수백만 명", "큼", "정부 개입 (세금·규제)"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1112,'클럽재','같이 써도 줄지 않지만 돈을 안 내면 막을 수 있는 재화','클럽재는 비경합성은 있지만 배제성도 있는 재화다. 여럿이 함께 써도 다른 사람 몫이 줄지 않지만, 요금을 내지 않은 사람은 쓰지 못하게 막을 수 있다. 유료 케이블 TV, OTT 구독, 안 막히는 유료 도로가 대표적이다.','','ㅋㄹㅈ',ARRAY['공공재','사적재','경합성과 배제성','공유지의 비극']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "케이블 TV는 여러 집이 봐도 화면이 줄지 않지만 요금을 안 내면 끊겨요.\n그래서 공공재가 아니라 클럽재예요."}, {"type": "table", "title": "재화의 4가지 분류", "columns": ["구분", "경합성 있음", "경합성 없음"], "rows": [["배제성 있음", "사적재 (빵, 옷)", "클럽재 (유료 케이블 TV, OTT)"], ["배제성 없음", "공유자원 (공동 어장)", "공공재 (국방, 가로등)"]]}, {"type": "table", "title": "도로는 상황에 따라 달라요", "columns": ["도로", "분류"], "rows": [["안 막히는 무료 도로", "공공재"], ["막히는 무료 도로", "공유자원"], ["안 막히는 유료 도로", "클럽재"], ["막히는 유료 도로", "사적재"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1113,'사적재','돈을 내야 쓸 수 있고 누가 쓰면 남의 몫이 줄어드는 재화','사적재는 경합성과 배제성을 모두 가진 재화다. 돈을 내지 않으면 쓰지 못하게 막을 수 있고, 한 사람이 쓰면 다른 사람이 쓸 수 있는 양이 줄어든다. 빵, 옷처럼 시장에서 사고파는 대부분의 물건이 여기에 속하며 시장 수요는 개인 수요를 가로로 더해 구한다.','','ㅅㅈㅈ',ARRAY['클럽재','공공재','경합성과 배제성','무임승차']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "내가 산 빵을 먹으면 다른 사람은 그 빵을 못 먹어요.\n돈을 안 내면 가게에서 가져갈 수도 없어요. 이런 보통 물건이 사적재예요."}, {"type": "table", "title": "사적재와 공공재 비교", "columns": ["구분", "사적재", "공공재"], "rows": [["경합성", "있음", "없음"], ["배제성", "있음", "없음"], ["시장 수요", "개인 수요를 가로로 더함", "한계편익을 세로로 더함"], ["시장에 맡기면", "잘 공급됨", "과소 공급"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1114,'가치재','사람들이 스스로 고르는 양보다 더 쓰는 게 좋다고 사회가 판단하는 재화','가치재는 개인이 스스로 선택하는 양보다 더 많이 소비하는 것이 바람직하다고 사회가 판단하는 재화다. 교육, 예방접종처럼 정부가 의무교육이나 무료 접종으로 소비를 늘린다. 반대로 담배, 마약처럼 덜 소비하게 하려는 재화는 비가치재라고 한다.','','ㄱㅊㅈ',ARRAY['온정주의','공공재','외부효과','죄악세']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "교육은 각자 알아서 고르게 두면 덜 받을 수 있어요.\n사회가 보기에 더 받는 게 좋으니 의무교육으로 늘려요."}, {"type": "table", "title": "가치재와 비가치재", "columns": ["구분", "예", "정부 대응"], "rows": [["가치재", "교육, 예방접종", "의무교육, 무료 접종"], ["비가치재", "담배, 마약", "세금, 금지"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1115,'온정주의','본인에게 좋다는 이유로 정부가 개인의 소비 선택에 개입하는 것','온정주의(가부장주의)는 정부가 개인에게 이롭다고 판단해 특정 재화의 소비를 늘리거나 줄이도록 개입하는 태도다. 의무교육, 담뱃세, 안전띠 착용 의무 같은 정책이 여기에 해당한다. 개인의 선택권인 소비자 주권을 침해한다는 비판을 함께 받는다.','','ㅇㅈㅈㅇ',ARRAY['가치재','죄악세','정부실패']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "부모가 아이에게 \"이게 너한테 좋아\"라며 채소를 먹게 하는 것과 비슷해요.\n정부가 개인 대신 무엇이 좋은지 판단하는 거예요."}, {"type": "table", "title": "온정주의를 둘러싼 시각", "columns": ["시각", "내용"], "rows": [["찬성", "정보 부족이나 근시안적 선택을 바로잡아요"], ["반대", "개인의 선택권(소비자 주권)을 침해해요"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1116,'신호 발송','정보를 가진 쪽이 자신의 특성을 상대에게 알리는 행동','신호 발송은 정보의 비대칭이 있을 때 정보를 가진 쪽이 자기 특성이나 상품의 질을 상대에게 믿을 만하게 알리는 행동이다. 자격증·학위 제출, 중고차 보증서, 무사고 이력 공개 등이 대표적이다. 계약 전에 숨겨진 특성 때문에 생기는 역선택을 줄이는 방법이다.','','ㅅㅎㅂㅅ',ARRAY['선별','역선택','정보의 비대칭성','도덕적 해이']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "좋은 중고차 주인은 성능점검기록부와 보증서를 내밀어 \"내 차는 괜찮아요\"라고 알려요.\n아는 쪽이 먼저 보여주는 게 신호 발송이에요."}, {"type": "table", "title": "신호 발송과 선별", "columns": ["방법", "누가", "예"], "rows": [["신호 발송", "정보를 가진 쪽", "자격증·학위, 중고차 보증서"], ["선별", "정보가 없는 쪽", "건강검진, 신용 조회"]], "caption": "아는 쪽은 신호, 모르는 쪽은 선별이에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1117,'선별','정보가 없는 쪽이 상대의 숨겨진 특성을 가려내려는 행동','선별은 정보의 비대칭이 있을 때 정보가 부족한 쪽이 상대의 특성을 알아내기 위해 하는 행동이다. 보험 가입 전 건강검진, 나이별 보험료, 대출 전 신용 조회가 대표적이다. 자기부담금이 다른 상품을 여러 개 내놓아 가입자가 스스로 고르게 하는 자기선택 장치도 선별에 속한다.','','ㅅㅂ',ARRAY['신호 발송','역선택','신용평가제도','정보의 비대칭성']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "보험사는 누가 건강한지 몰라서 가입 전에 건강검진 결과를 요구해요.\n모르는 쪽이 직접 가려내는 게 선별이에요."}, {"type": "flow", "title": "자기선택 장치로 선별하기", "steps": ["자기부담금이 다른 상품 여러 개 제시", "건강에 자신 있는 사람은 자기부담금 큰 싼 상품 선택", "위험한 사람은 비싼 상품 선택", "위험도가 자연스럽게 드러남"]}, {"type": "text", "title": "왜 중요할까?", "body": "선별이 없으면 보험사는 평균 보험료를 받게 되고, 건강한 사람이 빠져나가는 역선택이 생겨요."}]'::jsonb,ARRAY['tesat']::text[]),
(1118,'3면 등가의 법칙','국민소득을 생산·지출·분배 쪽에서 재면 모두 같다는 원칙','한 나라가 일정 기간 새로 만든 가치는 생산, 지출, 분배(소득) 세 방향에서 잴 수 있다. 만든 것은 누군가 사서 쓰고, 그 돈은 임금·이자·지대·이윤으로 나뉘므로 세 값은 모두 같다. 지출 쪽에서 재면 GDP = 소비 + 투자 + 정부지출 + 순수출이 된다.','','3ㅁㄷㄱㅇㅂㅊ',ARRAY['국내총생산(GDP)','부가가치','최종 생산물','총지출']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "빵집이 빵 1만 원어치를 만들면(생산)\n손님이 1만 원을 내고 사요(지출).\n그 1만 원은 직원 월급, 가게 월세, 사장 이윤으로 나뉘어요(분배).\n그래서 세 숫자는 항상 같아요."}, {"type": "table", "title": "세 방향에서 재는 GDP", "columns": ["측면", "무엇을 더하나"], "rows": [["생산", "산업별 부가가치 (농업, 제조업, 서비스업 등)"], ["지출", "소비 + 투자 + 정부지출 + 순수출"], ["분배(소득)", "임금, 이자, 지대, 이윤"]]}, {"type": "flow", "title": "돈이 한 바퀴 도는 흐름", "steps": ["기업이 생산", "누군가 구입(지출)", "판매 대금이 소득으로 분배", "소득으로 다시 지출"], "caption": "어디서 재든 같은 돈이 돌기 때문에 값이 같아요."}]'::jsonb,ARRAY['tesat']::text[]),
(1119,'최종 생산물','다른 물건을 만드는 데 다시 쓰이지 않고 최종 사용자에게 가는 재화와 서비스','최종 생산물은 소비자가 쓰거나 기업이 투자로 들여오는 등 생산 과정의 마지막에 놓인 재화와 서비스다. GDP는 중간재를 빼고 최종 생산물의 시장 가치만 더하는데, 중간재까지 더하면 같은 가치를 두 번 세게 되기 때문이다. 최종 생산물의 가치는 각 생산 단계에서 새로 더해진 부가가치의 합과 같다.','','ㅊㅈㅅㅅㅁ',ARRAY['국내총생산(GDP)','부가가치','중간소비','3면 등가의 법칙']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "밀 → 밀가루 → 빵으로 이어질 때\n마지막에 소비자가 사 먹는 빵이 최종 생산물이에요.\n밀과 밀가루 값은 이미 빵 값에 들어 있어서 따로 세지 않아요."}, {"type": "table", "title": "빵 한 개가 만들어지기까지", "columns": ["단계", "판매 가격", "새로 더한 가치"], "rows": [["농부 → 밀", "1,000원", "1,000원"], ["제분업자 → 밀가루", "1,500원", "500원"], ["제빵업자 → 빵", "2,500원", "1,000원"]], "caption": "빵 값 2,500원 = 부가가치 합 1,000 + 500 + 1,000원이에요.\n세 가격을 다 더한 5,000원은 두 번 센 값이에요."}, {"type": "text", "title": "왜 중요할까?", "body": "GDP를 계산할 때 무엇을 넣고 뺄지 정하는 기준이에요.\n중간재까지 세면 나라 경제 크기가 부풀려져요."}]'::jsonb,ARRAY['tesat']::text[]),
(1120,'거시경제학','물가·실업·성장처럼 나라 경제 전체의 움직임을 다루는 경제학 분야','거시경제학은 국민소득, 물가, 실업률, 이자율, 환율처럼 나라 경제 전체를 보여주는 변수를 연구한다. 소비자 한 명이나 기업 하나의 선택을 다루는 미시경제학과 짝을 이룬다. 1930년대 대공황 뒤 케인스의 이론과 함께 본격적으로 발전했다.','','ㄱㅅㄱㅈㅎ',ARRAY['국내총생산(GDP)','총수요','총공급','케인스 국민소득 결정이론']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "미시경제학이 나무 한 그루를 본다면\n거시경제학은 숲 전체를 봐요.\n나라 경제의 성적표인 GDP가 출발점이에요."}, {"type": "table", "title": "미시경제학과 거시경제학", "columns": ["구분", "미시경제학", "거시경제학"], "rows": [["보는 대상", "소비자, 기업 하나하나", "나라 경제 전체"], ["비유", "나무", "숲"], ["핵심 지표", "가격, 수량", "GDP, 물가, 실업률, 금리"]]}]'::jsonb,ARRAY['tesat']::text[])
